import React from 'react';
import { Link, useNavigate } from 'react-router-dom';

const Navbar = () => {
  const navigate = useNavigate();
  // التحقق من وجود التوكن في المتصفح
  const isAuthenticated = !!localStorage.getItem('token'); 

  const handleLogout = () => {
    localStorage.removeItem('token'); // حذف التوكن عند الخروج
    navigate('/auth'); // توجيه المستخدم لصفحة الدخول
    window.location.reload(); // تحديث الواجهة
  };

  return (
    <nav className="bg-studentDark p-4 shadow-md">
      <div className="container mx-auto flex justify-between items-center">
        <Link to="/" className="text-white text-2xl font-bold">
           My opportunities
        </Link>
        <div className="space-x-4 flex items-center">
          <Link to="/" className="text-gray-300 hover:text-white transition duration-200">
            Home
          </Link>
          <Link to="/opportunities" className="text-gray-300 hover:text-white transition duration-200">
            Opportunities
          </Link>

          {/* روابط تظهر فقط للمسجلين */}
          {isAuthenticated && (
            <>
              <Link to="/profile" className="text-gray-300 hover:text-white transition duration-200">
                Profile
              </Link>
              <Link to="/myapplication" style={{textDecoration:'none', color:'#4a3f6b', fontWeight:'500'}} >
                MyApplications
              </Link>
              <Link to="/students" className="text-gray-300 hover:text-white transition duration-200">
                Dashboard
              </Link>
            </>
          )}

          {/* تبديل زر الدخول بزر الخروج */}
          {!isAuthenticated ? (
            <Link to="/auth" className="text-gray-300 hover:text-white transition duration-200">
              Login / Registration
            </Link>
          ) : (
            <button 
              onClick={handleLogout}
              className="text-red-400 hover:text-red-600 transition duration-200 font-medium"
            >
              Logout
            </button>
          )}
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
